import{_ as d,H as r,f as a,i as e}from"./chunks/framework.nyB-Xt5O.js";const b=JSON.parse('{"title":"能力成长路线","description":"","frontmatter":{},"headers":[],"relativePath":"career/cd-2-growth-path.md","filePath":"career/cd-2-growth-path.md","lastUpdated":1779798726000}'),o={name:"career/cd-2-growth-path.md"};function l(i,t,h,n,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="能力成长路线" tabindex="-1">能力成长路线 <a class="header-anchor" href="#能力成长路线" aria-label="Permalink to &quot;能力成长路线&quot;">​</a></h1><blockquote><p>数据分析职业发展通常经历四个阶段：执行层 → 独立层 → 策略层 → 领导层。每个阶段的核心能力要求不同。</p></blockquote><h2 id="四个阶段概览" tabindex="-1">四个阶段概览 <a class="header-anchor" href="#四个阶段概览" aria-label="Permalink to &quot;四个阶段概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>年限</th><th>角色定位</th><th>典型产出</th></tr></thead><tbody><tr><td>初级 (Junior)</td><td>0-2 年</td><td>执行者 — 按要求完成数据提取和报表</td><td>SQL 查询、Excel 报表、简单的看板</td></tr><tr><td>中级 (Mid)</td><td>2-5 年</td><td>独立贡献者 — 主动发现问题并推动解决</td><td>专题分析报告、指标体系、实验评估</td></tr><tr><td>高级 (Senior)</td><td>5-8 年</td><td>策略制定者 — 驱动业务方向和数据产品建设</td><td>业务策略建议、数据产品规划、团队辅导</td></tr><tr><td>专家/管理 (Expert/Manager)</td><td>8 年+</td><td>方向制定者 — 搭建团队和数据文化</td><td>数据战略、组织搭建、方法论沉淀</td></tr></tbody></table><h2 id="第一阶段-初级-0-2-年-—-执行层" tabindex="-1">第一阶段：初级 (0-2 年) — 执行层 <a class="header-anchor" href="#第一阶段-初级-0-2-年-—-执行层" aria-label="Permalink to &quot;第一阶段：初级 (0-2 年) — 执行层&quot;">​</a></h2><p>这个阶段的核心是 <strong>快、准、稳</strong> 地完成任务。</p><p><strong>技能 checklist</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>SQL 基础查询</td><td>★★★</td><td>SELECT、WHERE、JOIN、GROUP BY、子查询，能独立完成取数需求</td></tr><tr><td>SQL 进阶</td><td>★★★</td><td>窗口函数、CTE、查询优化、常见面试题通过</td></tr><tr><td>Excel 数据分析</td><td>★★★</td><td>透视表、vlookup、条件格式、基础图表</td></tr><tr><td>BI 工具入门</td><td>★★☆</td><td>能用 Tableau/Power BI 搭建简单看板</td></tr><tr><td>业务理解</td><td>★★☆</td><td>理解自己负责的业务模块的核心指标</td></tr><tr><td>沟通执行</td><td>★★★</td><td>准确理解需求、按时交付、有问题及时反馈</td></tr></tbody></table><p><strong>典型工作内容</strong></p><ul><li>根据需求文档写 SQL 提取数据</li><li>维护和更新日报 / 周报</li><li>搭建基本的业务看板</li><li>对数据进行一致性校验</li></ul><h2 id="第二阶段-中级-2-5-年-—-独立层" tabindex="-1">第二阶段：中级 (2-5 年) — 独立层 <a class="header-anchor" href="#第二阶段-中级-2-5-年-—-独立层" aria-label="Permalink to &quot;第二阶段：中级 (2-5 年) — 独立层&quot;">​</a></h2><p>这个阶段的目标是 <strong>从&quot;执行&quot;走向&quot;分析&quot;</strong>，能够独立发现问题并给出 actionable 的建议。</p><p><strong>技能 checklist</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>统计学</td><td>★★★</td><td>描述统计、假设检验、AB 实验基础、回归分析</td></tr><tr><td>Python/R</td><td>★★★</td><td>pandas 数据处理、matplotlib/seaborn 可视化、基础的统计分析</td></tr><tr><td>指标体系</td><td>★★★</td><td>能独立搭建 OSM/UJM 模型，设计核心指标和过程指标</td></tr><tr><td>专题分析</td><td>★★★</td><td>能独立完成从问题定义→数据获取→分析→结论→建议的闭环</td></tr><tr><td>AB 实验</td><td>★★☆</td><td>了解实验设计原则、样本量计算、结果解读</td></tr><tr><td>项目管理</td><td>★★☆</td><td>同时处理多个需求，能合理安排优先级</td></tr><tr><td>沟通影响</td><td>★★★</td><td>能用数据和故事说服 stakeholders</td></tr></tbody></table><p><strong>典型工作内容</strong></p><ul><li>深度用户行为分析（留存、转化路径、分层）</li><li>产品功能上线效果评估</li><li>参与搭建公司核心指标体系</li><li>向业务方呈现分析结论并推动落地</li></ul><h2 id="第三阶段-高级-5-8-年-—-策略层" tabindex="-1">第三阶段：高级 (5-8 年) — 策略层 <a class="header-anchor" href="#第三阶段-高级-5-8-年-—-策略层" aria-label="Permalink to &quot;第三阶段：高级 (5-8 年) — 策略层&quot;">​</a></h2><p>这个阶段从&quot;分析&quot;走向&quot;策略&quot;，<strong>驱动业务方向</strong>，帮助团队做更重要的决策。</p><p><strong>技能 checklist</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>商业思维</td><td>★★★</td><td>理解公司战略、行业格局，分析能直接关联业务目标</td></tr><tr><td>数据产品</td><td>★★★</td><td>能主导内部 BI 平台／标签系统／实验平台的产品规划</td></tr><tr><td>实验与因果推断</td><td>★★★</td><td>能设计复杂的实验（MVT、Geo 实验），处理辛普森悖论等问题</td></tr><tr><td>团队辅导</td><td>★★☆</td><td>能指导初中级分析师，做代码 review 和分析框架 review</td></tr><tr><td>跨部门推动</td><td>★★★</td><td>能推动中大型项目跨团队协作落地</td></tr><tr><td>向上汇报</td><td>★★★</td><td>能从数据中提炼关键结论，用简洁的方式向 VP/CXO 汇报</td></tr></tbody></table><p><strong>典型工作内容</strong></p><ul><li>参与业务年度规划，输出数据维度的策略建议</li><li>搭建数据产品体系，提升团队数据效率</li><li>辅导初中级分析师，建立团队分析规范</li><li>负责跨 BU 的数据治理和统一口径项目</li></ul><h2 id="第四阶段-专家-管理-8-年-—-领导层" tabindex="-1">第四阶段：专家/管理 (8 年+) — 领导层 <a class="header-anchor" href="#第四阶段-专家-管理-8-年-—-领导层" aria-label="Permalink to &quot;第四阶段：专家/管理 (8 年+) — 领导层&quot;">​</a></h2><p>这个阶段的核心是 <strong>制定方向、搭建团队、构建文化</strong>。</p><p><strong>技能 checklist</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>数据战略</td><td>★★★</td><td>制定团队 1-3 年数据建设规划，匹配业务节奏</td></tr><tr><td>组织建设</td><td>★★★</td><td>搭建团队架构、招聘标准、晋升体系</td></tr><tr><td>数据文化</td><td>★★★</td><td>在公司层面推动数据驱动文化，提升全员数据素养</td></tr><tr><td>行业影响力</td><td>★★☆</td><td>通过文章、演讲、开源等方式建立个人或团队影响力</td></tr><tr><td>管理能力</td><td>★★★</td><td>目标设定、绩效管理、团队激励、冲突处理</td></tr></tbody></table><p><strong>典型工作内容</strong></p><ul><li>制定数据团队年度目标和 OKR</li><li>招聘和培养中高级数据人才</li><li>建设公司级数据平台和数据治理体系</li><li>向管理层汇报数据战略进度</li></ul><h2 id="成长建议" tabindex="-1">成长建议 <a class="header-anchor" href="#成长建议" aria-label="Permalink to &quot;成长建议&quot;">​</a></h2><ol><li><strong>不要只看年限</strong>：成长不是线性的，关键看你能不能产出下一阶段的价值。有人 3 年就达到高级水平，有人 8 年还在初中级。</li><li><strong>定期做 gap analysis</strong>：每半年回顾一次 checklist，找出当前最短板，集中突破。</li><li><strong>横向迁移是常态</strong>：数据分析师可以转向数据产品、数据科学、甚至业务运营。技术线和管理线各有优劣，根据自身偏好选择。</li><li><strong>软技能和硬技能同样重要</strong>：越往上走，沟通、影响、管理能力的权重越高。</li></ol>',30)])])}const u=d(o,[["render",l]]);export{b as __pageData,u as default};
